## 代码示例翻译与详细注释

### 示例1：顺序归并算法

```c
// 顺序归并函数
// 参数说明：
//   A: 输入数组A的指针
//   m: 数组A的元素个数
//   B: 输入数组B的指针
//   n: 数组B的元素个数
//   C: 输出数组C的指针
void merge_sequential(int *A, int m, int *B, int n, int *C) {
    int i = 0;  // A数组的当前索引
    int j = 0;  // B数组的当前索引
    int k = 0;  // C数组的当前索引

    // 主循环：比较A和B的当前元素，将较小的放入C
    // 循环继续直到任一数组遍历完毕
    while ((i < m) && (j < n)) {
        // 如果A[i] <= B[j]，选择A[i]（保证稳定性）
        if (A[i] <= B[j]) {
            C[k] = A[i];  // 将A[i]放入输出数组
            i++;           // 移动A的指针
        } else {
            C[k] = B[j];  // 将B[j]放入输出数组
            j++;           // 移动B的指针
        }
        k++;  // 移动输出指针
    }

    // 处理剩余元素：如果A数组还有剩余元素
    if (i == m) {
        // A数组已遍历完，将B数组剩余元素复制到C
        for (; j < n; j++) {
            C[k] = B[j];
            k++;
        }
    } else {
        // B数组已遍历完，将A数组剩余元素复制到C
        for (; i < m; i++) {
            C[k] = A[i];
            k++;
        }
    }
}
```

**算法分析**：
- **时间复杂度**：O(m + n)，每个元素被访问一次
- **空间复杂度**：O(1)，只使用常数额外空间
- **稳定性**：当A[i] == B[j]时，优先选择A[i]，保证稳定性

### 示例2：Co-rank函数实现

```c
// Co-rank函数：根据输出位置k确定输入数组A中的对应位置i
// 参数说明：
//   k: 输出数组C中的位置（rank）
//   A: 输入数组A的指针
//   m: 数组A的元素个数
//   B: 输入数组B的指针
//   n: 数组B的元素个数
// 返回值：co-rank值i（数组A中的位置）
int co_rank(int k, int *A, int m, int *B, int n) {
    int i, j;       // 当前的co-rank候选值
    int i_low, i_high;  // i的搜索范围边界
    int j_low, j_high;  // j的搜索范围边界

    // 初始化i的搜索范围
    // i不能超过k（因为i + j = k）
    // i也不能超过m（A数组的大小）
    i_low = (k > n) ? k - n : 0;  // i的最小可能值
    i_high = (k < m) ? k : m;      // i的最大可能值

    // 初始化j的搜索范围
    // j = k - i，由i的值决定
    j_low = (k > m) ? k - m : 0;  // j的最小可能值
    j_high = (k < n) ? k : n;      // j的最大可能值

    i = i_low;  // 从最小值开始搜索

    // 二分搜索主循环
    while (i_low <= i_high) {
        i = (i_low + i_high) / 2;  // 中间位置
        j = k - i;                  // 计算对应的j值

        // 检查条件1：A[i-1] <= B[j]
        // 如果不满足，说明i太大，需要在左半部分继续搜索
        if (i > 0 && j < n && A[i-1] > B[j]) {
            i_high = i - 1;  // 在左半部分搜索
        }
        // 检查条件2：B[j-1] < A[i]
        // 如果不满足，说明i太小，需要在右半部分继续搜索
        else if (j > 0 && i < m && B[j-1] >= A[i]) {
            i_low = i + 1;   // 在右半部分搜索
        }
        // 两个条件都满足，找到正确的co-rank值
        else {
            break;  // 退出循环
        }
    }

    return i;  // 返回co-rank值
}
```

**算法详解**：

这个co-rank函数使用二分搜索来找到正确的i值。搜索的关键在于理解两个条件的含义：

**条件1：A[i-1] ≤ B[j]**
- A[i-1]是A数组中最后一个应该出现在C[k]之前的元素
- B[j]是B数组中第一个可能出现在C[k]或之后的元素
- 这个条件确保所有应该在C[k]之前的A元素都已被包含

**条件2：B[j-1] < A[i]**
- B[j-1]是B数组中最后一个应该出现在C[k]之前的元素
- A[i]是A数组中第一个可能出现在C[k]或之后的元素
- 这个条件确保所有应该在C[k]之前的B元素都已被包含

**搜索过程**：
1. 如果A[i-1] > B[j]，说明i太大，需要减小i
2. 如果B[j-1] ≥ A[i]，说明i太小，需要增大i
3. 当两个条件都满足时，找到正确答案

**复杂度分析**：
- 时间复杂度：O(log(min(m, n)))
- 空间复杂度：O(1)

### 示例3：基本并行归并内核

```c
// 基本并行归并内核
// 参数说明：
//   A: 输入数组A（全局内存）
//   m: 数组A的元素个数
//   B: 输入数组B（全局内存）
//   n: 数组B的元素个数
//   C: 输出数组C（全局内存）
__global__ void merge_basic_kernel(int *A, int m, int *B, int n, int *C) {
    // 计算当前线程的全局索引
    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    // 计算总线程数
    int total_threads = gridDim.x * blockDim.x;

    // 计算当前线程负责的输出范围
    // 使用整数除法均匀分配工作
    int elements_per_thread = (m + n + total_threads - 1) / total_threads;

    // 当前线程负责的输出起始位置
    int k_curr = tid * elements_per_thread;
    // 当前线程负责的输出结束位置（下一个线程的起始位置）
    int k_next = (tid + 1) * elements_per_thread;

    // 确保不超过输出数组的边界
    if (k_curr > m + n) k_curr = m + n;
    if (k_next > m + n) k_next = m + n;

    // 调用co-rank函数确定输入子数组的起始位置
    int i_curr = co_rank(k_curr, A, m, B, n);  // A数组的起始位置
    int j_curr = k_curr - i_curr;               // B数组的起始位置

    // 调用co-rank函数确定输入子数组的结束位置
    int i_next = co_rank(k_next, A, m, B, n);   // A数组的结束位置
    int j_next = k_next - i_next;                // B数组的结束位置

    // 计算输入子数组的大小
    int a_size = i_next - i_curr;  // A子数组的大小
    int b_size = j_next - j_curr;  // B子数组的大小

    // 调用顺序归并函数处理分配的子数组
    merge_sequential(&A[i_curr], a_size, 
                     &B[j_curr], b_size, 
                     &C[k_curr]);
}
```

**内核执行流程**：

1. **工作分配阶段**：
   - 每个线程计算自己负责的输出范围
   - 使用均匀划分策略，每个线程处理大致相同数量的输出元素

2. **输入范围确定阶段**：
   - 调用co_rank函数确定输入子数组的起始和结束位置
   - 第一次调用确定起始位置，第二次调用确定结束位置

3. **归并执行阶段**：
   - 每个线程独立执行顺序归并
   - 所有线程并行工作，无需同步

**性能问题**：
- 内存访问不合并：相邻线程访问不相邻的内存位置
- 全局内存延迟：co-rank函数多次访问全局内存
- 无数据重用：每个数据元素只被访问一次

### 示例4：分块归并内核

```c
// 分块归并内核 - 使用共享内存提高内存访问效率
// 参数说明：
//   A: 输入数组A（全局内存）
//   m: 数组A的元素个数
//   B: 输入数组B（全局内存）
//   n: 数组B的元素个数
//   C: 输出数组C（全局内存）
//   TILE_SIZE: 每个块处理的元素数量
__global__ void merge_tiled_kernel(int *A, int m, int *B, int n, int *C) {
    // 共享内存缓冲区
    __shared__ int A_s[TILE_SIZE];  // A数组的缓冲区
    __shared__ int B_s[TILE_SIZE];  // B数组的缓冲区

    // 计算当前块负责的输出范围
    int block_start = blockIdx.x * TILE_SIZE;
    int block_end = min(block_start + TILE_SIZE, m + n);

    // 使用co-rank函数确定块级别的输入范围
    int i_start = co_rank(block_start, A, m, B, n);
    int i_end = co_rank(block_end, A, m, B, n);
    int j_start = block_start - i_start;
    int j_end = block_end - i_end;

    // 计算输入子数组的大小
    int a_size = i_end - i_start;
    int b_size = j_end - j_start;

    // 协作加载A数组数据到共享内存（合并访问）
    for (int i = threadIdx.x; i < a_size; i += blockDim.x) {
        A_s[i] = A[i_start + i];
    }

    // 协作加载B数组数据到共享内存（合并访问）
    for (int j = threadIdx.x; j < b_size; j += blockDim.x) {
        B_s[j] = B[j_start + j];
    }

    // 同步，确保所有数据加载完成
    __syncthreads();

    // 每个线程处理一部分输出元素
    int thread_start = threadIdx.x * (TILE_SIZE / blockDim.x);
    int thread_end = min(thread_start + (TILE_SIZE / blockDim.x), 
                         block_end - block_start);

    // 确定线程级别的输入范围
    int thread_i_start = co_rank(thread_start, A_s, a_size, B_s, b_size);
    int thread_i_end = co_rank(thread_end, A_s, a_size, B_s, b_size);
    int thread_j_start = thread_start - thread_i_start;
    int thread_j_end = thread_end - thread_i_end;

    // 在共享内存中执行归并
    merge_sequential(&A_s[thread_i_start], thread_i_end - thread_i_start,
                     &B_s[thread_j_start], thread_j_end - thread_j_start,
                     &C[block_start + thread_start]);
}
```

**优化要点**：

1. **合并的全局内存访问**：
   - 块内所有线程协作加载数据
   - 相邻线程加载相邻内存位置
   - 充分利用内存带宽

2. **共享内存的使用**：
   - 将频繁访问的数据缓存到共享内存
   - 减少全局内存访问次数
   - 提高访问速度

3. **两级并行**：
   - 块级别：确定块级别的输入输出范围
   - 线程级别：在共享内存中进一步划分工作

### 示例5：循环缓冲区归并内核

```c
// 循环缓冲区归并内核
// 使用固定大小的缓冲区支持任意长度的输入
#define BUFFER_SIZE 256

__global__ void merge_circular_buffer_kernel(int *A, int m, int *B, int n, int *C) {
    // 循环缓冲区
    __shared__ int A_buffer[BUFFER_SIZE];
    __shared__ int B_buffer[BUFFER_SIZE];

    // 缓冲区管理变量
    __shared__ int A_start, A_end;  // A缓冲区的有效数据范围
    __shared__ int B_start, B_end;  // B缓冲区的有效数据范围
    __shared__ int A_global_pos;    // A数组在全局内存中的当前位置
    __shared__ int B_global_pos;    // B数组在全局内存中的当前位置

    // 初始化（由线程0执行）
    if (threadIdx.x == 0) {
        A_start = A_end = 0;
        B_start = B_end = 0;
        A_global_pos = 0;
        B_global_pos = 0;
    }
    __syncthreads();

    // 归并主循环
    int c_pos = blockIdx.x * blockDim.x;  // 输出位置

    while (c_pos < m + n) {
        // 检查是否需要加载更多A数据
        if (A_end - A_start < BUFFER_SIZE / 2 && A_global_pos < m) {
            // 协作加载A数据
            int load_count = min(BUFFER_SIZE - (A_end - A_start), 
                                m - A_global_pos);
            for (int i = threadIdx.x; i < load_count; i += blockDim.x) {
                int buffer_idx = A_end % BUFFER_SIZE;
                A_buffer[buffer_idx] = A[A_global_pos + i];
            }
            if (threadIdx.x == 0) {
                A_global_pos += load_count;
                A_end += load_count;
            }
        }

        // 检查是否需要加载更多B数据
        if (B_end - B_start < BUFFER_SIZE / 2 && B_global_pos < n) {
            // 协作加载B数据
            int load_count = min(BUFFER_SIZE - (B_end - B_start), 
                                n - B_global_pos);
            for (int i = threadIdx.x; i < load_count; i += blockDim.x) {
                int buffer_idx = B_end % BUFFER_SIZE;
                B_buffer[buffer_idx] = B[B_global_pos + i];
            }
            if (threadIdx.x == 0) {
                B_global_pos += load_count;
                B_end += load_count;
            }
        }

        __syncthreads();

        // 执行归并操作
        // ...（归并逻辑）

        // 更新缓冲区指针
        if (threadIdx.x == 0) {
            A_start += consumed_A;
            B_start += consumed_B;
        }

        c_pos++;
    }
}
```

**循环缓冲区的优势**：

1. **固定内存占用**：
   - 不管输入多大，共享内存使用量固定
   - 适合处理大规模数据

2. **流式处理**：
   - 数据按需加载
   - 支持处理超出共享内存容量的数据

3. **高效的数据管理**：
   - 使用模运算实现循环索引
   - 避免数据移动开销

